import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream is = System.in;

    static int readByte() throws IOException {
        if (ptr == len) { len = is.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = readByte(); }
        return sb.toString();
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c != '-' && (c < '0' || c > '9')) c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = readByte(); }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        HashMap<String, Integer> occupied = new HashMap<>();
        PriorityQueue<Integer> freed = new PriorityQueue<>(); // released lockers, smallest first
        int nextId = 1, answer = 0;
        for (int i = 0; i < n; i++) {
            String visitor = next();
            Integer locker = occupied.remove(visitor);
            if (locker != null) freed.add(locker);
            else {
                answer = freed.isEmpty() ? nextId++ : freed.poll();
                occupied.put(visitor, answer);
            }
        }
        System.out.println(answer);
    }
}

